// Campi che il 12 NON tocca mai in aggiornamento (anche se arrivassero dal browser o da Claude).
const CAMPI_VIETATI_AGGIORNA = ['cliente', 'ig_user_id', 'fb_page_id', 'id_luogo', 'attivo', 'cartella_drive', 'whatsapp_titolare', 'marchio',
  'approvazione_testi', 'approvazione_storie', 'ig_user_id_2', 'fb_page_id_2', 'anteprime_con_persone', 'row_number'];
