    testo: taglia(el && el.testo, 300), prezzo: taglia(el && el.prezzo, 40), citazione: taglia(el && el.citazione, 300) }));
  const testoFoto = taglia([testo(x && x.testo_letto), ...elementi.map((el) => el.citazione)].filter(Boolean).join('\n'), 20000);
  return { n, testo: testoFoto, elementi, persone: !!(x && x.persone === true) };
};
const MAX_BYTE_FOTO = 3.75 * 1024 * 1024;
// m4 · Tetto sul TOTALE delle foto di una chiamata: 20 MB di file diventano circa 26,7 MB in base64, sotto i 32 MB
// che l'API accetta per una richiesta (oltre: 413, che fermerebbe tutto il giro). Le foto in più si saltano con avviso.
const MAX_TOTALE_FOTO = 20 * 1024 * 1024;
// ── fine funzioni di servizio ──
const a = $('Ancora libera?').first().json;
const scritta = $('Esito della cartella').first().json;
const { __avvisi_12: avvisiCartella, ...riga } = scritta;
const avvisi = [...(avvisiCartella || [])];
const esitoScrittura = $('Scrivi il cliente').first().json || {};
const foglio = leggiFoglio($input.first().json);
const righe = foglio.righe.filter((r) => testo(r.cliente).toLowerCase() === testo(riga.cliente).toLowerCase());
let stato = 'ok';
if (!foglio.ok) { stato = 'non_verificata'; avvisi.push(`Non ho potuto rileggere il foglio per controllare la riga (${foglio.errore}).`); }
else if (righe.length === 0) stato = 'mancante';
else if (righe.length > 1) { stato = 'doppia'; avvisi.push(`ATTENZIONE: la chiave «${riga.cliente}» ora compare ${righe.length} volte (righe ${righe.map((r) => r.row_number).join(', ')}): cancella le righe in più.`); }
const errScrittura = esitoScrittura.error ? taglia(esitoScrittura.error.message || esitoScrittura.error, 160) : '';
const nome = riga.nome_locale;
const conf = a.campi_da_confermare || [];
const cartella = testo(riga.cartella_drive);
const passi = [
  conf.length ? `1) Controlla i campi da confermare: ${conf.join(', ')}.` : '1) Ricontrolla la riga nella scheda Clienti.',
  '2) Lancia «00 · Attiva cliente»: scrive ig_user_id e/o fb_page_id (ne serve almeno uno).',
  cartella ? '3) cartella_drive è pronta.' : '3) Metti il link della cartella in cartella_drive: senza, il motore non lavora il cliente.',
  '4) Solo alla fine metti attivo = si. Con attivo = no il motore salta la riga.',
];
let titolo = 'Cliente creato';
let testa;
if (stato === 'mancante') { titolo = 'Da controllare'; testa = `Non trovo la riga di «${nome}» nella scheda Clienti${errScrittura ? ` (errore di Google: ${errScrittura})` : ''}. Controlla il foglio prima di riprovare.`; }
else testa = `Ho aggiunto «${nome}» alla scheda Clienti con attivo = no.`;
const schermo = `${testa}\n\nCampi da confermare: ${conf.length}${conf.length ? ' (' + conf.join(', ') + ')' : ''}.\nFrasi da verificare: ${testo(riga.da_verificare) ? testo(riga.da_verificare).split(';').length : 0}.\nCartella Drive: ${cartella || 'nessuna'}.`
  + (avvisi.length ? `\n\nAvvisi:\n${avvisi.map((x) => `• ${x}`).join('\n')}` : '') + `\n\nProssimi passi:\n${passi.join('\n')}`;
// Telegram: niente whatsapp_titolare, niente testi di Meta. Solo nome, conteggi, cartella, avvisi e passi.
const telegram = unisci([
  stato === 'mancante' ? `⚠️ <b>Nuovo cliente: riga non trovata</b> · ${esc(nome)}` : `🆕 <b>Cliente creato</b>: ${esc(nome)} (attivo = no)`,
  `Campi da confermare: ${conf.length}${conf.length ? ' (' + esc(conf.join(', ')) + ')' : ''}`,
  cartella ? `📁 <a href="${esc(cartella)}">Cartella Drive</a>` : '📁 Cartella Drive: nessuna',
  avvisi.length ? `ℹ️ ${esc(taglia(avvisi.join(' '), 1500))}` : null,
  `Prossimi passi:\n${esc(passi.join('\n'))}`,
]);
return [{ json: { stato, titolo_schermo: titolo, testo_schermo: perSchermo(schermo), testo_telegram: mascheraMeta(telegram) } }];

